CREATE TABLE "acquisition_funnel_benchmarks" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"funnel_key" text NOT NULL,
	"benchmark_key" text NOT NULL,
	"sector" "prospection_sector",
	"value" real NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "acquisition_funnel_benchmarks" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "acquisition_funnels" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"funnel_key" text NOT NULL,
	"label" text NOT NULL,
	"description" text NOT NULL,
	"steps" jsonb NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "acquisition_funnels_funnel_key_unique" UNIQUE("funnel_key")
);
--> statement-breakpoint
ALTER TABLE "acquisition_funnels" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "monthly_metrics" ADD COLUMN "acquisition_metrics" jsonb DEFAULT '{}'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "acquisition_funnel_benchmarks" ADD CONSTRAINT "acquisition_funnel_benchmarks_funnel_key_acquisition_funnels_funnel_key_fk" FOREIGN KEY ("funnel_key") REFERENCES "public"."acquisition_funnels"("funnel_key") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "acquisition_funnel_benchmarks_scope_idx" ON "acquisition_funnel_benchmarks" USING btree ("funnel_key","benchmark_key","sector");
--> statement-breakpoint
