INSERT INTO "acquisition_funnel_benchmarks" ("funnel_key", "benchmark_key", "value")
SELECT seeds."funnel_key", benchmark_values.key, benchmark_values.value::real
FROM seeds CROSS JOIN LATERAL jsonb_each_text(seeds."benchmarks") AS benchmark_values(key, value)
ON CONFLICT DO NOTHING;
